window.KH_SURA(42, {"sura": "الشورى", "n": 42, "ayat": {"1": "حم", "2": "عسق", "3": "كَذَلِكَ يُوحِي إِلَيْكَ وَإِلَى الَّذِينَ مِنْ قَبْلِكَ اللَّهُ الْعَزِيزُ الْحَكِيمُ", "4": "لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَلِيُّ الْعَظِيمُ", "5": "تَكَادُ السَّمَاوَاتُ يَتَفَطَّرْنَ مِنْ فَوْقِهِنَّ وَالْمَلَائِكَةُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيَسْتَغْفِرُونَ لِمَنْ فِي الْأَرْضِ أَلَا إِنَّ اللَّهَ هُوَ الْغَفُورُ الرَّحِيمُ", "6": "وَالَّذِينَ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ اللَّهُ حَفِيظٌ عَلَيْهِمْ وَمَا أَنْتَ عَلَيْهِمْ بِوَكِيلٍ", "7": "وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ قُرْآنًا عَرَبِيًّا لِتُنْذِرَ أُمَّ الْقُرَى وَمَنْ حَوْلَهَا وَتُنْذِرَ يَوْمَ الْجَمْعِ لَا رَيْبَ فِيهِ فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ", "8": "وَلَوْ شَاءَ اللَّهُ لَجَعَلَهُمْ أُمَّةً وَاحِدَةً وَلَكِنْ يُدْخِلُ مَنْ يَشَاءُ فِي رَحْمَتِهِ وَالظَّالِمُونَ مَا لَهُمْ مِنْ وَلِيٍّ وَلَا نَصِيرٍ", "9": "أَمِ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ فَاللَّهُ هُوَ الْوَلِيُّ وَهُوَ يُحْيِ الْمَوْتَى وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "10": "وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ ذَلِكُمُ اللَّهُ رَبِّي عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ", "11": "فَاطِرُ السَّمَاوَاتِ وَالْأَرْضِ جَعَلَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا وَمِنَ الْأَنْعَامِ أَزْوَاجًا يَذْرَؤُكُمْ فِيهِ لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ", "12": "لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ يَبْسُطُ الرِّزْقَ لِمَنْ يَشَاءُ وَيَقْدِرُ إِنَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ", "13": "شَرَعَ لَكُمْ مِنَ الدِّينِ مَا وَصَّى بِهِ نُوحًا وَالَّذِي أَوْحَيْنَا إِلَيْكَ وَمَا وَصَّيْنَا بِهِ إِبْرَاهِيمَ وَمُوسَى وَعِيسَى أَنْ أَقِيمُوا الدِّينَ وَلَا تَتَفَرَّقُوا فِيهِ كَبُرَ عَلَى الْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ اللَّهُ يَجْتَبِي إِلَيْهِ مَنْ يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ يُنِيبُ", "14": "وَمَا تَفَرَّقُوا إِلَّا مِنْ بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ إِلَى أَجَلٍ مُسَمًّى لَقُضِيَ بَيْنَهُمْ وَإِنَّ الَّذِينَ أُورِثُوا الْكِتَابَ مِنْ بَعْدِهِمْ لَفِي شَكٍّ مِنْهُ مُرِيبٍ", "15": "فَلِذَلِكَ فَادْعُ وَاسْتَقِمْ كَمَا أُمِرْتَ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ وَقُلْ آمَنْتُ بِمَا أَنْزَلَ اللَّهُ مِنْ كِتَابٍ وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ اللَّهُ رَبُّنَا وَرَبُّكُمْ لَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ اللَّهُ يَجْمَعُ بَيْنَنَا وَإِلَيْهِ الْمَصِيرُ", "16": "وَالَّذِينَ يُحَاجُّونَ فِي اللَّهِ مِنْ بَعْدِ مَا اسْتُجِيبَ لَهُ حُجَّتُهُمْ دَاحِضَةٌ عِنْدَ رَبِّهِمْ وَعَلَيْهِمْ غَضَبٌ وَلَهُمْ عَذَابٌ شَدِيدٌ", "17": "اللَّهُ الَّذِي أَنْزَلَ الْكِتَابَ بِالْحَقِّ وَالْمِيزَانَ وَمَا يُدْرِيكَ لَعَلَّ السَّاعَةَ قَرِيبٌ", "18": "يَسْتَعْجِلُ بِهَا الَّذِينَ لَا يُؤْمِنُونَ بِهَا وَالَّذِينَ آمَنُوا مُشْفِقُونَ مِنْهَا وَيَعْلَمُونَ أَنَّهَا الْحَقُّ أَلَا إِنَّ الَّذِينَ يُمَارُونَ فِي السَّاعَةِ لَفِي ضَلَالٍ بَعِيدٍ", "19": "اللَّهُ لَطِيفٌ بِعِبَادِهِ يَرْزُقُ مَنْ يَشَاءُ وَهُوَ الْقَوِيُّ الْعَزِيزُ", "20": "مَنْ كَانَ يُرِيدُ حَرْثَ الْآخِرَةِ نَزِدْ لَهُ فِي حَرْثِهِ وَمَنْ كَانَ يُرِيدُ حَرْثَ الدُّنْيَا نُؤْتِهِ مِنْهَا وَمَا لَهُ فِي الْآخِرَةِ مِنْ نَصِيبٍ", "21": "أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ وَلَوْلَا كَلِمَةُ الْفَصْلِ لَقُضِيَ بَيْنَهُمْ وَإِنَّ الظَّالِمِينَ لَهُمْ عَذَابٌ أَلِيمٌ", "22": "تَرَى الظَّالِمِينَ مُشْفِقِينَ مِمَّا كَسَبُوا وَهُوَ وَاقِعٌ بِهِمْ وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فِي رَوْضَاتِ الْجَنَّاتِ لَهُمْ مَا يَشَاءُونَ عِنْدَ رَبِّهِمْ ذَلِكَ هُوَ الْفَضْلُ الْكَبِيرُ", "23": "ذَلِكَ الَّذِي يُبَشِّرُ اللَّهُ عِبَادَهُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ قُلْ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَى وَمَنْ يَقْتَرِفْ حَسَنَةً نَزِدْ لَهُ فِيهَا حُسْنًا إِنَّ اللَّهَ غَفُورٌ شَكُورٌ", "24": "أَمْ يَقُولُونَ افْتَرَى عَلَى اللَّهِ كَذِبًا فَإِنْ يَشَإِ اللَّهُ يَخْتِمْ عَلَى قَلْبِكَ وَيَمْحُ اللَّهُ الْبَاطِلَ وَيُحِقُّ الْحَقَّ بِكَلِمَاتِهِ إِنَّهُ عَلِيمٌ بِذَاتِ الصُّدُورِ", "25": "وَهُوَ الَّذِي يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَعْفُو عَنِ السَّيِّئَاتِ وَيَعْلَمُ مَا تَفْعَلُونَ", "26": "وَيَسْتَجِيبُ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَيَزِيدُهُمْ مِنْ فَضْلِهِ وَالْكَافِرُونَ لَهُمْ عَذَابٌ شَدِيدٌ", "27": "وَلَوْ بَسَطَ اللَّهُ الرِّزْقَ لِعِبَادِهِ لَبَغَوْا فِي الْأَرْضِ وَلَكِنْ يُنَزِّلُ بِقَدَرٍ مَا يَشَاءُ إِنَّهُ بِعِبَادِهِ خَبِيرٌ بَصِيرٌ", "28": "وَهُوَ الَّذِي يُنَزِّلُ الْغَيْثَ مِنْ بَعْدِ مَا قَنَطُوا وَيَنْشُرُ رَحْمَتَهُ وَهُوَ الْوَلِيُّ الْحَمِيدُ", "29": "وَمِنْ آيَاتِهِ خَلْقُ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَثَّ فِيهِمَا مِنْ دَابَّةٍ وَهُوَ عَلَى جَمْعِهِمْ إِذَا يَشَاءُ قَدِيرٌ", "30": "وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَنْ كَثِيرٍ", "31": "وَمَا أَنْتُمْ بِمُعْجِزِينَ فِي الْأَرْضِ وَمَا لَكُمْ مِنْ دُونِ اللَّهِ مِنْ وَلِيٍّ وَلَا نَصِيرٍ", "32": "وَمِنْ آيَاتِهِ الْجَوَارِ فِي الْبَحْرِ كَالْأَعْلَامِ", "33": "إِنْ يَشَأْ يُسْكِنِ الرِّيحَ فَيَظْلَلْنَ رَوَاكِدَ عَلَى ظَهْرِهِ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ", "34": "أَوْ يُوبِقْهُنَّ بِمَا كَسَبُوا وَيَعْفُ عَنْ كَثِيرٍ", "35": "وَيَعْلَمَ الَّذِينَ يُجَادِلُونَ فِي آيَاتِنَا مَا لَهُمْ مِنْ مَحِيصٍ", "36": "فَمَا أُوتِيتُمْ مِنْ شَيْءٍ فَمَتَاعُ الْحَيَاةِ الدُّنْيَا وَمَا عِنْدَ اللَّهِ خَيْرٌ وَأَبْقَى لِلَّذِينَ آمَنُوا وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ", "37": "وَالَّذِينَ يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ وَإِذَا مَا غَضِبُوا هُمْ يَغْفِرُونَ", "38": "وَالَّذِينَ اسْتَجَابُوا لِرَبِّهِمْ وَأَقَامُوا الصَّلَاةَ وَأَمْرُهُمْ شُورَى بَيْنَهُمْ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ", "39": "وَالَّذِينَ إِذَا أَصَابَهُمُ الْبَغْيُ هُمْ يَنْتَصِرُونَ", "40": "وَجَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ إِنَّهُ لَا يُحِبُّ الظَّالِمِينَ", "41": "وَلَمَنِ انْتَصَرَ بَعْدَ ظُلْمِهِ فَأُولَئِكَ مَا عَلَيْهِمْ مِنْ سَبِيلٍ", "42": "إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَظْلِمُونَ النَّاسَ وَيَبْغُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ أُولَئِكَ لَهُمْ عَذَابٌ أَلِيمٌ", "43": "وَلَمَنْ صَبَرَ وَغَفَرَ إِنَّ ذَلِكَ لَمِنْ عَزْمِ الْأُمُورِ", "44": "وَمَنْ يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ وَلِيٍّ مِنْ بَعْدِهِ وَتَرَى الظَّالِمِينَ لَمَّا رَأَوُا الْعَذَابَ يَقُولُونَ هَلْ إِلَى مَرَدٍّ مِنْ سَبِيلٍ", "45": "وَتَرَاهُمْ يُعْرَضُونَ عَلَيْهَا خَاشِعِينَ مِنَ الذُّلِّ يَنْظُرُونَ مِنْ طَرْفٍ خَفِيٍّ وَقَالَ الَّذِينَ آمَنُوا إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا إِنَّ الظَّالِمِينَ فِي عَذَابٍ مُقِيمٍ", "46": "وَمَا كَانَ لَهُمْ مِنْ أَوْلِيَاءَ يَنْصُرُونَهُمْ مِنْ دُونِ اللَّهِ وَمَنْ يُضْلِلِ اللَّهُ فَمَا لَهُ مِنْ سَبِيلٍ", "47": "اسْتَجِيبُوا لِرَبِّكُمْ مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لَا مَرَدَّ لَهُ مِنَ اللَّهِ مَا لَكُمْ مِنْ مَلْجَإٍ يَوْمَئِذٍ وَمَا لَكُمْ مِنْ نَكِيرٍ", "48": "فَإِنْ أَعْرَضُوا فَمَا أَرْسَلْنَاكَ عَلَيْهِمْ حَفِيظًا إِنْ عَلَيْكَ إِلَّا الْبَلَاغُ وَإِنَّا إِذَا أَذَقْنَا الْإِنْسَانَ مِنَّا رَحْمَةً فَرِحَ بِهَا وَإِنْ تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ فَإِنَّ الْإِنْسَانَ كَفُورٌ", "49": "لِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ يَخْلُقُ مَا يَشَاءُ يَهَبُ لِمَنْ يَشَاءُ إِنَاثًا وَيَهَبُ لِمَنْ يَشَاءُ الذُّكُورَ", "50": "أَوْ يُزَوِّجُهُمْ ذُكْرَانًا وَإِنَاثًا وَيَجْعَلُ مَنْ يَشَاءُ عَقِيمًا إِنَّهُ عَلِيمٌ قَدِيرٌ", "51": "وَمَا كَانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللَّهُ إِلَّا وَحْيًا أَوْ مِنْ وَرَاءِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ مَا يَشَاءُ إِنَّهُ عَلِيٌّ حَكِيمٌ", "52": "وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ رُوحًا مِنْ أَمْرِنَا مَا كُنْتَ تَدْرِي مَا الْكِتَابُ وَلَا الْإِيمَانُ وَلَكِنْ جَعَلْنَاهُ نُورًا نَهْدِي بِهِ مَنْ نَشَاءُ مِنْ عِبَادِنَا وَإِنَّكَ لَتَهْدِي إِلَى صِرَاطٍ مُسْتَقِيمٍ", "53": "صِرَاطِ اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ أَلَا إِلَى اللَّهِ تَصِيرُ الْأُمُورُ"}, "units": [{"aya": 7, "title": "تأويل: ﴿فريق في الجنة وفريق في السعير﴾", "tabari": {"page": "20/472", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿فريق في الجنة وفريق في السعير﴾. يقول: منهم فريق في الجنة، وهم الذين آمنوا بالله، واتبعوا ما جاءهم به رسوله ﷺ، ﴿وفريق في السعير﴾. يقول: ومنهم فريق في الموقدة من نار الله المسعورة على أهلها، وهم الذين كفروا بالله، وخالفوا ما جاءهم به رسوله.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿فريق في الجنة وفريق في السعير﴾. فرفع. وقد تقدم الكلام قبل ذلك بقوله: ﴿لتنذر أم القرى ومن حولها﴾ بالنصب؛ لأنه أريد به الابتداء، كما يقال: رأيت العسكر؛ مقتول أو منهزم. بمعنى: منهم مقتول، ومنهم منهزم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 1, "imgs": ["042_001_1.png", "042_001_2.png"], "pages": [456, 457], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 11, "title": "في معنى قوله: ﴿يذرؤكم فيه﴾. في هذا الموضع", "tabari": {"page": "20/475", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معنى ذلك: يخلقكم فيه", "taqdim": 0, "n_athar": 4, "qailun": [["مجاهد", "تابعي"], ["السدي", "تابعي"], ["منصور", ""]], "athar": [68843, 68847, 68849, 68850]}, {"n": 2, "t": "بل معناه: يعيشكم فيه", "taqdim": 0, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["قتادة", "تابعي"]], "athar": [68846, 68848]}]}, "mawaqif": [{"taliq": 5790, "mi": 1, "aya": 11, "alam": "ابن جرير", "fil": "ذكرهما", "kind": "نقل", "ref": "20/ 476", "qawl": "", "nass": "وهذان القولان وإن اختلفا في اللفظ من قائليهما فقد يحتمل توجيههما إلى معنى واحد، وهو أن يكون القائل في معناه: يعيشكم فيه. أراد بقوله ذلك: يحييكم بعيشكم به كما يحيي من لم يخلق بتكوينه إياه، ونفخه الروح فيه حتى يعيش حيا", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["042_002_1.png"], "pages": [457], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5790, "masala": "قوله: {يذرؤكم فيه}", "sigha": "في المسألة قولان", "nasib": "", "aqwal": [{"n": 1, "t": "يخلقكم فيه", "ashab": "", "athar": []}, {"n": 2, "t": "يعيشكم فيه", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 15, "title": "المشار إليه ب {ذلك}", "mawsua": {"taliq": 5793, "masala": "المشار إليه ب {ذلك}", "sigha": "ذكر قولين", "nasib": "ابن جرير", "aqwal": [{"n": 1, "t": "أنه التوحيد. كما في قول مقاتل", "ashab": "", "athar": []}, {"n": 2, "t": "أنه القرآن", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5793, "mi": 1, "aya": 15, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 485", "qawl": "مقاتل", "nass": "لأنه في سياق خبر الله -جل ثناؤه- عما شرع لكم من الدين لنبيه محمد صلى الله عليه وسلم بإقامته، ولم يأت من الكلام ما يدل على انصرافه عنه إلى غيره", "qawaid": ["السياق"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "قوله: {بالحق}", "mawsua": {"taliq": 5798, "masala": "قوله: {بالحق}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون المعنى بأن كان ذلك حقا واجبا للمصلحة والهدى", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون المعنى مضمنا الحق، أي: بالحق في أحكامه وأوامره", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5798, "mi": 1, "aya": 17, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 508", "qawl": "", "nass": "وقوله: {بالحق} يحتمل أن يكون المعنى بأن كان ذلك حقا واجبا للمصلحة والهدى، ويحتمل أن يكون المعنى مضمنا الحق، أي: بالحق في أحكامه وأوامره", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 21, "title": "المراد بالشركاء", "mawsua": {"taliq": 5801, "masala": "المراد بالشركاء", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يكون المراد بهم: الشياطين والمغوين من أسلافهم، ويكون الضمير في {لهم} للكفار المعاصرين لمحمد صلى الله عليه وسلم، أي: شرع الشركاء لهم ما لم يأذن به الله. فالاشتراك هاهنا هو في الكفر والغواية، وليس بشركة الإشراك بالله", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون المراد بالشركاء: الأصنام والأوثان، على معنى: أم لهم أصنام جعلوها شركاء لله في ألوهيته، ويكون الضمير في: {شرعوا} لهؤلاء المعاصرين من الكفار ولآبائهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5801, "mi": 1, "aya": 21, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 510", "qawl": "", "nass": "والشركاء في هذه الآية يحتمل أن يكون المراد بهم: الشياطين والمغوين من أسلافهم، ويكون الضمير في {لهم} للكفار المعاصرين لمحمد صلى الله عليه وسلم، أي: شرع الشركاء لهم ما لم يأذن به الله. فالاشتراك هاهنا هو في الكفر والغواية، وليس بشركة الإشراك بالله، ويحتمل أن يكون المراد بالشركاء: الأصنام والأوثان، على معنى: أم لهم أصنام جعلوها شركاء لله في ألوهيته، ويكون الضمير في: {شرعوا} لهؤلاء المعاصرين من الكفار ولآبائهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 23, "title": "في معنى قوله: ﴿إلا المودة في القربى﴾", "tabari": {"page": "20/495", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب، وأشبهها بظاهر التنزيل قول من قال: معناه: قل لا أسألكم عليه أجرا يا معشر قريش، إلا أن تودوني في قرابتي منكم، وتصلوا الرحم التي بيني وبينكم.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: إلا أن تودونى في قرابتى منكم، وتصلوا رحمى بينى وبينكم", "taqdim": 0, "n_athar": 14, "qailun": [["ابن عباس", "صحابي"], ["طاوس", ""], ["عكرمة", "تابعي"], ["أبي مالك", "تابعي"], ["قتادة", "تابعي"], ["مجاهد", "تابعي"], ["السدي", "تابعي"], ["ابن زيد", "تابع التابعين"], ["عطاء بن دينار", "تابع التابعين"]], "athar": [68961, 68962, 68963, 68966, 68969, 68970, 68971, 68972, 68973, 68974, 68976, 68977, 68979, 68980, 68981, 68984, 68990, 68991, 68998, 68999, 69001, 69002, 69004, 69006, 69007, 69009, 69010, 69012]}, {"n": 2, "t": "بل معنى ذلك: قل لمن اتبعك من المؤمنين: لا أسألكم على ما جئتكم به أجرا، إلا أن تودوا قرابتى", "taqdim": 0, "n_athar": 4, "qailun": [["أبي الديلم", ""], ["ابن عباس", "صحابي"], ["سعيد بن جبير", "تابعي"], ["أبي إسحاق", "تابعي"]], "athar": [68961, 68962, 68963, 68969, 68970, 68971, 68972, 68973, 68974, 68976, 68977, 68979, 68980, 68981, 68982, 68983, 69000, 69006]}, {"n": 3, "t": "بل معنى ذلك: قل لا أسألكم أيها الناس على ما جئتكم به أجرا، إلا أن توددوا إلى الله، وتتقربوا بالعمل الصالح والطاعة", "taqdim": 0, "n_athar": 5, "qailun": [["الحسن", "تابعي"], ["قتادة", "تابعي"]], "athar": [68966, 68992, 68993, 68994, 68995, 68996, 68998, 68999, 69010]}, {"n": 4, "t": "بل معنى ذلك: إلا أن تصلوا قرابتكم", "taqdim": 0, "n_athar": 1, "qailun": [["عبد الله بن القاسم", "تابعي"]], "athar": [68997]}]}, "mawaqif": [{"taliq": 5808, "mi": 1, "aya": 23, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 502", "qawl": "الأول", "nass": "وإنما قلت: هذا التأويل أولى بتأويل الآية لدخول {في} في قوله: {إلا المودة في القربى}، ولو كان معنى ذلك على ما قاله من قال: إلا أن تودوا قرابتي، أو تقربوا إلى الله. لم يكن لدخول {في} في الكلام في هذا الموضع وجه معروف، ولكان التنزيل: إلا مودة القربى. إن عنى به الأمر بمودة قرابة رسول الله صلى الله عليه وسلم، أو إلا المودة بالقربى، أو: ذا القربى. إن عنى به التودد والتقرب. وفي دخول {في} في الكلام أوضح الدليل على أن معناه: إلا مودتي في قرابتي منكم، وأن الألف واللام في المودة أدخلتا بدلا من الإضافة، كما قيل: {فإن الجنة هي المأوى} [النازعات: 41]", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5808, "mi": 1, "aya": 23, "alam": "ابن تيمية", "fil": "رجح", "kind": "ترجيح", "ref": "5/ 495 - 497", "qawl": "الأول", "nass": "", "qawaid": ["أقوال السلف", "اللغة", "القرآن والنظائر"], "tabi": ""}, {"taliq": 5808, "mi": 1, "aya": 23, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "12/ 271", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن تيمية"}], "mushid": {"i": 3, "imgs": ["042_003_1.png"], "pages": [457], "n": 4, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5808, "masala": "قوله: {إلا المودة في القربى}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "إلا أن تودوني في قرابتي منكم، وتصلوا رحمي بيني وبينكم", "ashab": "", "athar": []}, {"n": 2, "t": "قل لمن تبعك من المؤمنين: لا أسألكم على ما جئتكم به أجرا إلا أن تودوا قرابتي", "ashab": "", "athar": []}, {"n": 3, "t": "قل لا أسألكم أيها الناس على ما جئتكم به أجرا إلا أن توددوا إلى الله، وتتقربوا بالعمل الصالح والطاعة", "ashab": "", "athar": []}, {"n": 4, "t": "إلا أن تصلوا قرابتكم", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن تيمية", "r"], ["ابن كثير", "r"]]}, "t": {"1": [["ابن جرير", "r"], ["ابن تيمية", "r"], ["ابن كثير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["اللغة"], "ابن تيمية": ["أقوال السلف", "اللغة", "القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 26, "title": "تأويل: ﴿ويزيدهم من فضله﴾", "tabari": {"page": "20/507", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿ويزيدهم من فضله﴾. يقول تعالى ذكره: ويزيد الذين آمنوا وعملوا الصالحات - مع إجابته إياهم دعاءهم، وإعطائه إياهم مسألتهم - من فضله، على مسألتهم إياه؛ بأن يعطيهم ما لم يسألوه.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إن ذلك الفضل الذي ضمن جل ثناؤه أن يزيدهموه، هو أن يشفعهم في إخوان إخوانهم إذا هم شفعوا في إخوانهم، فشفعوا فيهم", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5815, "mi": 0, "aya": 26, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "20/ 507", "qawl": "", "nass": "قوله: {ويزيدهم من فضله} يقول -تعالى ذكره-: ويزيد الذين آمنوا وعملوا الصالحات -مع إجابته إياهم دعاءهم، وإعطائه إياهم مسألتهم- من فضله، على مسألتهم إياه؛ بأن يعطيهم ما لم يسألوه", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 26, "title": "في معنى قوله: ﴿ويستجيب الذين آمنوا وعملوا الصالحات﴾", "tabari": {"page": "20/508", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "بل معنى ذلك: ويجيب الذين آمنوا. وهذا القول يحتمل وجهين؛ أحدهما النصب ، بمعنى: ويجيب الله الذين آمنوا. والآخر ما قاله صاحب القول الذي ذكرناه", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿ويستجيب الذين آمنوا﴾. يكون ﴿الذين﴾ في موضع نصب بمعنى: ويجيب الله الذين آمنوا. وقد جاء في التنزيل: ﴿فاستجاب لهم ربهم﴾ [آل عمران: ١٩٥]، والمعنى، [والله أعلم: فأجابهم] . ربهم، إلا أنك إذا قلت: استجاب. أدخلت اللام في المفعول، وإذا قلت: أجاب. حذفت اللام، ويكون \"استجابهم\" بمعنى: استجاب لهم. كما قال: ﴿وإذا كالوهم أو وزنوهم يخسرون﴾ [المطففين: ٣]. والمعنى، والله أعلم: وإذا كالوا لهم أو وزنوا لهم يخسرون. قال: ويكون ﴿الذين﴾ في", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 30, "title": "تأويل: ﴿وما أصابكم من مصيبة فبما كسبت أيديكم ويعفو عن كثير وما أنتم بمعجزين في الأرض وما لكم من دو﴾", "tabari": {"page": "20/514", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: وما يصيبكم أيها الناس من مصيبة في الدنيا في أنفسكم أو أهليكم أو أموالكم، ﴿فبما كسبت أيديكم﴾. يقول: فإنما يصيبكم ذلك عقوبة من الله لكم بما اجترمتم من الآثام فيما بينكم وبين ربكم، ويعفو لكم ربكم عن كثير من إجرامكم، ولا يعاقبكم بها.", "taqdim": 1, "n_athar": 3, "qailun": [["قتادة", "تابعي"], ["ابن عباس", "صحابي"]], "athar": [69059, 69062]}, {"n": 2, "t": "بل عنى بذلك: وما عوقبتم به في الدنيا من عقوبة، بحد حددتموه على ذنب استوجبتموه عليه، ﴿فبما كسبت أيديكم﴾. يقول: فيما عملتم من معصية الله، ﴿ويعفو عن كثير﴾، فلا يوجب عليكم فيها حدا", "taqdim": 0, "n_athar": 1, "qailun": [["عن الحسن", ""]], "athar": []}]}, "mawaqif": [], "mushid": {"i": 4, "imgs": ["042_004_1.png"], "pages": [457], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 34, "title": "معنى الآية", "mawsua": {"taliq": 5820, "masala": "معنى الآية", "sigha": "ذكر قولين", "nasib": "ابن كثير", "aqwal": [{"n": 1, "t": "لأهلكها وأغرقها بذنوب أهلها", "ashab": "", "athar": []}, {"n": 2, "t": "لو شاء لأرسل الريح قوية عاتية، فأخذت السفن وأحالتها عن سيرها المستقيم، فصرفتها ذات اليمين أو ذات الشمال، آبقة لا تسير على طريق، ولا إلى جهة مقصد", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5820, "mi": 1, "aya": 34, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 284", "qawl": "الثاني", "nass": "وهذا القول هو يتضمن هلاكها، وهو مناسب للأول، وهو أنه تعالى لو شاء لسكن الريح فوقفت، أو لقواه فشردت وأبقت وهلكت، ولكن من لطفه ورحمته أنه يرسله بحسب الحاجة، كما يرسل المطر بقدر الكفاية، ولو أنزله كثيرا جدا لهدم البنيان، أو قليلا لما أنبت الزرع والثمار، حتى إنه يرسل إلى مثل بلاد مصر سيحا من أرض أخرى غيرها؛ لأنهم لا يحتاجون إلى مطر، ولو أنزل عليهم لهدم بنيانهم، وأسقط جدرانهم", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 39, "title": "في الباغى الذي حمد تعالى ذكره المنتصر منه بعد بغيه عليه", "tabari": {"page": "20/523", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هو المشرك إذا بغى على المسلم", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [69122]}, {"n": 2, "t": "بل هو كل باغ بغى، فحمد المنتصر منه", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [69119]}]}, "mawaqif": [{"taliq": 5823, "mi": 1, "aya": 39, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 524", "qawl": "العموم", "nass": "لأن الله لم يخصص من ذلك معنى دون معنى، بل حمد كل منتصر بحق ممن بغى عليه", "qawaid": ["العموم"], "tabi": ""}, {"taliq": 5823, "mi": 1, "aya": 39, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 523 - 524", "qawl": "الأول", "nass": "وقالت هذه الفرقة -وهي الجمهور-: إن المؤمن إذا بغى على مؤمن وظلمه، فلا يجوز للآخر أن ينتصف منه بنفسه ويجازيه على ظلمه. مثال ذلك: أن يخون الإنسان آخر، ثم يتمكن الإنسان من خيانته، فمذهب مالك? أن لا يفعل، وهو مذهب جماعة عظيمة معه، ولم يروا هذه الآية من هذا المعنى، واحتجوا بقول النبي صلى الله عليه وسلم: «أد الأمانة إلى من ائتمنك، ولا تخن من خانك»", "qawaid": [], "tabi": ""}], "mushid": {"i": 5, "imgs": ["042_005_1.png"], "pages": [458], "n": 2, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 5823, "masala": "الباغي الذي حمد -تعالى ذكره- المنتصر منه بعد بغيه عليه", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه المشرك إذا بغى على المسلم", "ashab": "", "athar": []}, {"n": 2, "t": "أن الآية في المجروح ينتصف من الجارح بالقصاص", "ashab": "", "athar": []}, {"n": 3, "t": "أنه كل باغ ومعتد", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {"2": [["ابن جرير", "r"]]}, "gen": [["ابن جرير", "رجّح العموم"]], "rules": {"ابن جرير": ["العموم"]}, "rulesD": {}}}, {"aya": 41, "title": "في المعني بذلك ﴿ولمن انتصر بعد ظلمه فأولئك ما عليهم من سبيل إنما السبيل على الذين يظلمون الناس ويبغون في ا﴾", "tabari": {"page": "20/527", "sarih": 1, "tarjih": "والصواب من القول في ذلك أن يقال: إنه معني به كل منتصر من ظالمه.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى به كل منتصر ممن أساء إليه، مسلما كان المسيء أو كافرا", "taqdim": 0, "n_athar": 3, "qailun": [["الانتصار", ""], ["قتادة", "تابعي"]], "athar": [69145]}, {"n": 2, "t": "بل عنى به الانتصار من أهل الشرك، وقال: هو منسوخ", "taqdim": 0, "n_athar": 1, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [69150]}]}, "mawaqif": [{"taliq": 5825, "mi": 1, "aya": 41, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 528", "qawl": "الأول", "nass": "والصواب من القول أن يقال: إنه معني به كل منتصر من ظالمه، وأن الآية محكمة غير منسوخة؛ للعلة التي بينت في الآية قبلها", "qawaid": [], "tabi": ""}], "mushid": {"i": 6, "imgs": ["042_006_1.png"], "pages": [458], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5825, "masala": "المعني بقوله: {ولمن انتصر بعد ظلمه}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "عنى به كل منتصر ممن أساء إليه، مسلما كان المسيء أو كافرا", "ashab": "", "athar": []}, {"n": 2, "t": "عنى به الانتصار من أهل الشرك. وهذا منسوخ", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 45, "title": "في معنى قوله: ﴿من طرف خفي﴾ الله", "tabari": {"page": "20/532", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "معناه: من طرف ذليل. وكأن معنى الكلام: من طرف قد خفى من ذله", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["مجاهد", "تابعي"]], "athar": [69164, 69165]}, {"n": 2, "t": "بل معنى ذلك: أنهم كانوا يسارقون النظر", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [69167]}]}, "mawaqif": [{"taliq": 5828, "mi": 1, "aya": 45, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 533", "qawl": "الأول", "nass": "أنهم ينظرون إلى النار من طرف ذليل", "qawaid": ["أقوال السلف", "اللغة", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5828, "mi": 1, "aya": 45, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 526 - 527", "qawl": "الأول", "nass": "وقال قتادة والسدي: المعنى: يسارقون النظر، لما كانوا من الهم وسوء الحال لا يستطيعون النظر بجميع العين، وإنما ينظرون من بعضها. قال: {من طرف خفي} أي: قليل. فالطرف هنا على هذا التأويل يحتمل أن يكون مصدرا، أي: يطرف طرفا خفيا", "qawaid": [], "tabi": ""}, {"taliq": 5828, "mi": 1, "aya": 45, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 533", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5828, "mi": 1, "aya": 45, "alam": "ابن عطية", "fil": "انتقده", "kind": "نقد", "ref": "", "qawl": "", "nass": "وفي هذا التأويل تكلف", "qawaid": [], "tabi": ""}], "mushid": {"i": 7, "imgs": ["042_007_1.png"], "pages": [458], "n": 2, "rajih": [1], "daif": [], "match": true}, "mawsua": {"taliq": 5828, "masala": "قوله: {من طرف خفي}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "من طرف ذليل", "ashab": "", "athar": []}, {"n": 2, "t": "أنهم يسارقون النظر", "ashab": "", "athar": []}]}, "tags": {"m": {"1": [["ابن جرير", "r"]]}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["أقوال السلف", "اللغة", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 45, "title": "في ذلك ﴿ينظرون من طرف خفي﴾", "tabari": {"page": "20/533", "sarih": 1, "tarjih": "والصواب من القول في ذلك القول الذي ذكرناه عن ابن عباس ومجاهد، وهو أن معناه: أنهم ينظرون إلى النار من طرف ذليل، وصفه الله جل ثناؤه بالخفاء؛ للذلة التي قد ركبتهم، حتى كادت أعينهم أن تغور فتذهب.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "جعل الطرف العين، كأنه قال: ونظرهم من عين ضعيفة. والله أعلم. قال: وقال يونس : إن ﴿من طرف﴾ مثل \"بطرف\"، كما تقول العرب: ضربته في السيف، و: ضربته بالسيف", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إنما قيل: ﴿من طرف خفي﴾. لأنه لا يفتح عينه، إنما ينظر ببعضها", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "إنما قيل: ﴿من طرف خفي﴾. لأنهم ينظرون إلى النار بقلوبهم؛ لأنهم يحشرون عميا", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 45, "title": "خسران الأهل", "mawsua": {"taliq": 5829, "masala": "خسران الأهل", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يراد به: أهلوهم الذين كانوا في الدنيا", "ashab": "", "athar": []}, {"n": 2, "t": "أن يراد به: أهلوهم الذين كانوا يكونون لهم في الجنة أن لو دخلوها", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5829, "mi": 1, "aya": 45, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 527", "qawl": "", "nass": "وخسران الأهلين يحتمل أن يراد به: أهلوهم الذين كانوا في الدنيا، ويحتمل أن يراد به: أهلوهم الذين كانوا يكونون لهم في الجنة أن لو دخلوها", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 52, "title": "في معنى الروح في هذا الموضع ﴿وكذلك أوحينا إليك روحا من أمرنا ما كنت تدري ما الكتاب ولا الإيمان ولكن جعلناه نورا نهدي به﴾", "tabari": {"page": "20/541", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى به الرحمة", "taqdim": 0, "n_athar": 1, "qailun": [["الحسن", "تابعي"]], "athar": [69230]}, {"n": 2, "t": "معناه: وحيا من أمرنا", "taqdim": 0, "n_athar": 1, "qailun": [["السدي", "تابعي"]], "athar": [69232, 69239, 69242, 69248]}]}, "mawaqif": [], "mushid": {"i": 8, "imgs": ["042_008_1.png"], "pages": [458], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 52, "title": "قوله: {جعلناه}", "mawsua": {"taliq": 5833, "masala": "قوله: {جعلناه}", "sigha": "ذكر قولين", "nasib": "ابن القيم", "aqwal": [{"n": 1, "t": "أنه عائد على الكتاب", "ashab": "", "athar": []}, {"n": 2, "t": "أنه عائد على الإيمان", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5833, "mi": 1, "aya": 52, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 434", "qawl": "", "nass": "والصحيح أنه يعود على الروح في قوله: {روحا من أمرنا}", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 5833, "mi": 1, "aya": 52, "alam": "ابن تيمية", "fil": "قال", "kind": "قول", "ref": "5/ 513 - 514", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن القيم"}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [], "others": {"0": [{"id": 5781, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 498) أن هذه السورة مكية بإجماع من أكثر المفسرين.", "mawaqif": [{"taliq": 5781, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 498", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 5782, "kinds": "تعليق", "text": "علق ابنُ كثير (12/ 253) على هذا الأثر بقوله: «أثر غريب عجيب منكر».", "mawaqif": [{"taliq": 5782, "mi": 0, "aya": 0, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "12/ 253", "qawl": "", "nass": "أثر غريب عجيب منكر", "qawaid": [], "tabi": ""}]}], "3": [{"id": 5783, "kinds": "نقل", "text": "ذكر ابن جرير (20/ 465) هذا القول دون تعيين قائله.", "mawaqif": [{"taliq": 5783, "mi": 0, "aya": 3, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 465", "qawl": "دون تعيين", "nass": "", "qawaid": [], "tabi": ""}]}], "5": [{"id": 5784, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (21/ 466 - 467) غير قول السُّدّيّ، وقول قتادة، والضَّحّاك، ومحمد بن قيس، وابن عباس من طريق عطية العَوفيّ.", "mawaqif": []}, {"id": 5785, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 468) غير قول ابن عباس.", "mawaqif": []}, {"id": 5786, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 501) قول السُّدّي، ووجّهه، فقال: «وقال السُّدّيّ ما معناه: إنّ ظاهر الآية العموم، ومعناها الخصوص في المؤمن، فكأنه قال: {ويَسْتَغْفِرُونَ لِمَن فِي الأَرْضِ} من المؤمنين؛ إذ الكفار عليهم لعنة الله والملائكة والناس أجمعين».", "mawaqif": [{"taliq": 5786, "mi": 0, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 501", "qawl": "السدي", "nass": "وقال السدي ما معناه: إن ظاهر الآية العموم، ومعناها الخصوص في المؤمن، فكأنه قال: {ويستغفرون لمن في الأرض} من المؤمنين؛ إذ الكفار عليهم لعنة الله والملائكة والناس أجمعين", "qawaid": [], "tabi": ""}]}, {"id": 5787, "kinds": "نقد،نقل", "text": "انتقد ابنُ عطية (7/ 501) -مستندًا إلى دلالة العقل- دعوى النسخ في الآية، فقال: «قالت فرقة: هذا منسوخ بقوله تعالى في آية أخرى: {ويَسْتَغْفِرُونَ لِلَّذِينَ آمَنُوا} [غافر: 7]. وهذا قول ضعيف؛ لأن النسخ في الأخبار لا يُتصور». وذكر قولًا آخر في الآية، وقوّاه مستندًا إلى السياق، فقال: «وقالت فرقة: بل هي على عمومها، لكن استغفار الملائكة ليس بطلب غفران الله تعالى للكفرة على أن يبقوا كفرة، وإنما استغفارهم لهم بمعنى طلب الهداية التي تؤدي إلى الغفران لهم، وكأن الملائكة تقول: اللهم، اهدِ أهل الأرض، واغفر لهم. ويؤيد هذا التأويل تأكيده صفة الغفران والرحمة لنفسه بالاستفتاح، وذلك قوله: {ألا إنَّ اللَّهَ هُوَ الغَفُورُ الرَّحِيمُ} أي: لما كان الاستغفار لجميع مَن في الأرض يبعد أن يجاب، رجّى عز وجل بأن استفتح الكلام تهيئة لنفس السامع، فقال: ألا إنّ الله هو الذي يُطلب هذا منه؛ إذ هذه أوصافه، وهو أهل المغفرة».", "mawaqif": [{"taliq": 5787, "mi": 0, "aya": 5, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 501", "qawl": "", "nass": "قالت فرقة: هذا منسوخ بقوله تعالى في آية أخرى: {ويستغفرون للذين آمنوا} [غافر: 7]. وهذا قول ضعيف؛ لأن النسخ في الأخبار لا يتصور", "qawaid": ["الدلالة العقلية", "السياق"], "tabi": ""}]}], "7": [{"id": 5788, "kinds": "تعليق،نقل", "text": "ذكر ابنُ كثير (12/ 259) هذا الأثر مرفوعًا وموقوفًا، ثم علّق بقوله: «وهذا الموقوف أشبه بالصواب».", "mawaqif": [{"taliq": 5788, "mi": 0, "aya": 7, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 259", "qawl": "", "nass": "وهذا الموقوف أشبه بالصواب", "qawaid": [], "tabi": ""}]}], "11": [{"id": 5789, "kinds": "ترجيح،نقل", "text": "ذكر ابن عطية (7/ 503) اختلافًا في المراد بالأزواج في الآية، ورجّح مستندًا إلى ظاهر الآية أنّ المراد بالأزواج: الإناث، فقال: «وقوله تعالى: {جَعَلَ لَكُمْ مِن أنْفُسِكُمْ أزْواجًا} يريد: زوج الإنسان الأنثى، وبهذه النعمة اتفق الذرء، وليست الأزواج هاهنا الأنواع، وأما الأزواج المذكورة مع الأنعام فالظاهر أيضًا والمتسق أنه يريد: إناث الذكران، ويحتمل أن يريد: الأنواع، والأول أظهر».", "mawaqif": [{"taliq": 5789, "mi": 0, "aya": 11, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 503", "qawl": "", "nass": "وقوله تعالى: {جعل لكم من أنفسكم أزواجا} يريد: زوج الإنسان الأنثى، وبهذه النعمة اتفق الذرء، وليست الأزواج هاهنا الأنواع، وأما الأزواج المذكورة مع الأنعام فالظاهر أيضا والمتسق أنه يريد: إناث الذكران، ويحتمل أن يريد: الأنواع، والأول أظهر", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}]}], "13": [{"id": 5791, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (7/ 505) أن اتفاق النبوات: «كان في المعتقدات، أو في جملة أمرها، مِن أن كل نبوة فإنما مضمنها معتقدات وأحكام، فيجيء المعنى على هذا: شرع لكم شرعة هي كشرعة نوح وإبراهيم وموسى وعيسى? في أنها ذات المعتقدات المشهورة التي هي في كل نبوءة وذات أحكام كما كانت تلك كلها». ثم بيّن أن قول قتادة يتخرّج على هذا المعنى، وكذا قول الحكم، ثم قال: «وأما الأحكام بانفرادها فهي في الشرائع مختلفة، وهي المراد في قوله تعالى: {لِكُلٍّ جَعَلْنا مِنكُمْ شِرْعَةً ومِنهاجًا} [المائدة: 48]».", "mawaqif": [{"taliq": 5791, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 505", "qawl": "", "nass": "كان في المعتقدات، أو في جملة أمرها، من أن كل نبوة فإنما مضمنها معتقدات وأحكام، فيجيء المعنى على هذا: شرع لكم شرعة هي كشرعة نوح وإبراهيم وموسى وعيسى? في أنها ذات المعتقدات المشهورة التي هي في كل نبوءة وذات أحكام كما كانت تلك كلها", "qawaid": [], "tabi": ""}]}], "14": [{"id": 5792, "kinds": "بيان،نقل", "text": "على هذا القول فالإشارة إلى اليهود والنصارى، وهو ما ذكره ابنُ عطية (7/ 506)، وذكر قولًا آخر بأن الإشارة للعرب، ثم بيّن أن الضمير في قوله: {لفي شك منه} يحتمل عدة احتمالات، فقال: «والضمير في قوله: {لَفِي شَكٍّ} يحتمل أن يعود على الكِتاب، أو على محمد، أو على الأجل المسمى، أي: في شكٍّ مِن البعث على قول مَن رأى الإشارة إلى العرب».", "mawaqif": [{"taliq": 5792, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 506", "qawl": "", "nass": "والضمير في قوله: {لفي شك} يحتمل أن يعود على الكتاب، أو على محمد، أو على الأجل المسمى، أي: في شك من البعث على قول من رأى الإشارة إلى العرب", "qawaid": [], "tabi": ""}]}], "15": [{"id": 5794, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 507): «قوله تعالى: {وأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ} قالت فرقة: اللام في {لِأَعْدِلَ} بمعنى: أن؛ لأن التقدير: بأن أعدل بينكم. وقالت فرقة: المعنى: وأمرت بما أمرت به من التبليغ والشرع لكي أعدل بينكم. فحذف من الكلام ما يدل الظاهر عليه».", "mawaqif": [{"taliq": 5794, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 507", "qawl": "", "nass": "قوله تعالى: {وأمرت لأعدل بينكم} قالت فرقة: اللام في {لأعدل} بمعنى: أن؛ لأن التقدير: بأن أعدل بينكم. وقالت فرقة: المعنى: وأمرت بما أمرت به من التبليغ والشرع لكي أعدل بينكم. فحذف من الكلام ما يدل الظاهر عليه", "qawaid": [], "tabi": ""}]}, {"id": 5795, "kinds": "نقل", "text": "ذكر ابنُ كثير (12/ 263) نحو هذا عن السُّدّي، وقوّاه مستندًا إلى زمن النُّزول، فقال: «قال السُّدّي: وذلك قبل نزول آية السيف. وهذا مُتَّجِه؛ لأن هذه الآية مكية، وآية السيف بعد الهجرة».", "mawaqif": [{"taliq": 5795, "mi": 0, "aya": 15, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 263", "qawl": "", "nass": "قال السدي: وذلك قبل نزول آية السيف. وهذا متجه؛ لأن هذه الآية مكية، وآية السيف بعد الهجرة", "qawaid": ["سبب النزول وأحواله"], "tabi": ""}]}], "16": [{"id": 5796, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 508) في عود الضمير في قوله: {استجيب له} عدة احتمالات، فقال: «والضمير في: {لَهُ} يحتمل أن يعود على اللَّه تعالى، أي: بعد ما دخل في دينه. ويحتمل أن يعود على الدين والشرع. ويحتمل أن يعود على محمد صلى الله عليه وسلم».", "mawaqif": [{"taliq": 5796, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 508", "qawl": "", "nass": "والضمير في: {له} يحتمل أن يعود على الله تعالى، أي: بعد ما دخل في دينه. ويحتمل أن يعود على الدين والشرع. ويحتمل أن يعود على محمد صلى الله عليه وسلم", "qawaid": [], "tabi": ""}]}], "17": [{"id": 5797, "kinds": "توجيه،بيان،تعليق،نقل،حصر", "text": "لم يذكر ابنُ جرير (20/ 490) غير قول قتادة ومجاهد. وذكرهما كذلك ابنُ عطية (7/ 508 - 509)، ثم أورد قولًا آخر عن مجاهد: أن الميزان هو الذي بين يدي الناس. ثم وجّهه بقوله: «ولا شك أنه داخل في العدل وجزء منه، وكل شيء من الأمور، فالعدل فيه إنما هو بوزن وتقدير مستقيم، فيحتاج في الأجرام إلى آلة، وهي العمود والكفّتان التي بأيدي البشر، ويحتاج في المعاني إلى هيئات في النفوس وفهوم توازن بين الأشياء».\nوعلّق ابنُ تيمية (5/ 486) على هذا القول وعلى قول من فسّره بالعدل بقوله: «وهما متلازمان».", "mawaqif": [{"taliq": 5797, "mi": 0, "aya": 17, "alam": "ابن تيمية", "fil": "علق", "kind": "تعليق", "ref": "5/ 486", "qawl": "وعلى قول", "nass": "وهما متلازمان", "qawaid": [], "tabi": ""}]}], "20": [{"id": 5799, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 491 - 492) غير قول ابن زيد، والسُّدّي، وقتادة، وابن عباس من طريق عطية العَوفيّ.", "mawaqif": []}, {"id": 5800, "kinds": "غيره", "text": "قال ابن كثير (12/ 265 - 266): «{ومن كان يريد حرث الدنيا نؤته منها وما له في الآخرة من نصيب} أي: ومَن كان إنما سعيه ليحصل له شيء من الدنيا، وليس له إلى الآخرة همة البتة بالكلية، حرمه الله الآخرة، والدنيا إن شاء أعطاه منها، وإن لم يشأ لم يحصل له لا هذه ولا هذه، وفاز هذا الساعي بهذه النية بالصفقة الخاسرة في الدنيا والآخرة. والدليل على هذا أن هذه الآية هاهنا مقيدة بالآية التي في» سبحان «وهي قوله تعالى: {من كان يريد العاجلة عجلنا له فيها ما نشاء لمن نريد ثم جعلنا له جهنم يصلاها مذموما مدحورا ومن أراد الآخرة وسعى لها سعيها وهو مؤمن فأولئك كان سعيهم مشكورا كلا نمد هؤلاء وهؤلاء من عطاء ربك وما كان عطاء ربك محظورا انظر كيف فضلنا بعضهم على بعض وللآخرة أكبر درجات وأكبر تفضيلا} [الإسراء: 18 - 21]».", "mawaqif": [{"taliq": 5800, "mi": 0, "aya": 20, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "12/ 265 - 266", "qawl": "", "nass": "{ومن كان يريد حرث الدنيا نؤته منها وما له في الآخرة من نصيب} أي: ومن كان إنما سعيه ليحصل له شيء من الدنيا، وليس له إلى الآخرة همة البتة بالكلية، حرمه الله الآخرة، والدنيا إن شاء أعطاه منها، وإن لم يشأ لم يحصل له لا هذه ولا هذه، وفاز هذا الساعي بهذه النية بالصفقة الخاسرة في الدنيا والآخرة. والدليل على هذا أن هذه الآية هاهنا مقيدة بالآية التي في", "qawaid": [], "tabi": ""}]}], "23": [{"id": 5802, "kinds": "نقد،بيان،نقل", "text": "ذكر ابنُ كثير (12/ 270) هذا الأثر، ثم انتقد -مستندًا إلى أحوال النزول والسياق- ما أفاده من نزول الآية بالمدينة، فقال: «وذكر نزولها في المدينة فيه نظر؛ لأن السورة مكية، وليس يظهر بين هذه الآية الكريمة وبين السياق مناسبة».", "mawaqif": [{"taliq": 5802, "mi": 0, "aya": 23, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "12/ 270", "qawl": "", "nass": "وذكر نزولها في المدينة فيه نظر؛ لأن السورة مكية، وليس يظهر بين هذه الآية الكريمة وبين السياق مناسبة", "qawaid": ["سبب النزول وأحواله", "السياق"], "tabi": ""}]}, {"id": 5803, "kinds": "ترجيح،نقل", "text": "ذكر ابن عطية (7/ 513) القول بالنسخ في الآية، ثم رجّح أنها محكمة بقوله: «والصواب أنها محكمة». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 5803, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 513", "qawl": "بالنسخ في", "nass": "والصواب أنها محكمة", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 5804, "kinds": "نقد،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 512) هذا الأثر، ثم علّق قائلًا: «وقريش كلها عندي قربى، وإن كانت تتفاضل، وقد رُوي عن النبي صلى الله عليه وسلم أنه قال: «مَن مات على حُبِّ آل محمد مات شهيدًا، ومَن مات على بُغضهم لم يشم رائحة الجنة»».\nوانتقده ابنُ كثير (12/ 271) مستندًا إلى ضعف إسناده، وإلى أحوال النُّزول، فقال: «وذِكْرُ نزول هذه الآية في المدينة بعيد؛ فإنها مكية، ولم يكن إذ ذاك لفاطمة أولاد بالكلية، فإنها لم تتزوج بعلي إلا بعد بدر من السنة الثانية من الهجرة».", "mawaqif": [{"taliq": 5804, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 512", "qawl": "", "nass": "وقريش كلها عندي قربى، وإن كانت تتفاضل، وقد روي عن النبي صلى الله عليه وسلم أنه قال: «من مات على حب آل محمد مات شهيدا، ومن مات على بغضهم لم يشم رائحة الجنة»", "qawaid": [], "tabi": ""}, {"taliq": 5804, "mi": 0, "aya": 23, "alam": "ابن كثير", "fil": "انتقده", "kind": "نقد", "ref": "12/ 271", "qawl": "", "nass": "وذكر نزول هذه الآية في المدينة بعيد؛ فإنها مكية، ولم يكن إذ ذاك لفاطمة أولاد بالكلية، فإنها لم تتزوج بعلي إلا بعد بدر من السنة الثانية من الهجرة", "qawaid": ["نقد الرواية (السند، الإسرائيليات)", "سبب النزول وأحواله"], "tabi": ""}]}, {"id": 5805, "kinds": "نقل", "text": "ذكر ابن عطية (7/ 513) قول ابن عباس، ووجّهه، فقال: «وقال ابن عباس أيضًا: معنى الآية: من قُربى الطاعة والتزلّف إلى الله تعالى، كأنه قال: إلا أن تودني، لأني أقربكم من الله، وأريد هدايتكم وأدعوكم إليها».", "mawaqif": [{"taliq": 5805, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 513", "qawl": "ابن عباس", "nass": "وقال ابن عباس أيضا: معنى الآية: من قربى الطاعة والتزلف إلى الله تعالى، كأنه قال: إلا أن تودني، لأني أقربكم من الله، وأريد هدايتكم وأدعوكم إليها", "qawaid": [], "tabi": ""}]}, {"id": 5806, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 513) قول عبد الله بن القاسم، ثم علّق بقوله: «فالآية على هذا أمر بصلة الرحم».", "mawaqif": [{"taliq": 5806, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 513", "qawl": "عبد الله", "nass": "فالآية على هذا أمر بصلة الرحم", "qawaid": [], "tabi": ""}]}, {"id": 5807, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 511 - 512) قول قتادة، وعلّق عليه، فقال: «فالآية على هذا هي استعطاف ما، ودفع أذى، وطلب سلامة منهم، وذلك كله منسوخ بآية السيف، ويحتمل على هذا التأويل أن يكون معنى الكلام استدعاء نصرهم، أي: لا أسألكم غرامة ولا شيئًا إلا أن تودُّوني لقرابتي منكم، وأن تكونوا أولى بي من غيركم».", "mawaqif": [{"taliq": 5807, "mi": 0, "aya": 23, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 511 - 512", "qawl": "قتادة", "nass": "فالآية على هذا هي استعطاف ما، ودفع أذى، وطلب سلامة منهم، وذلك كله منسوخ بآية السيف، ويحتمل على هذا التأويل أن يكون معنى الكلام استدعاء نصرهم، أي: لا أسألكم غرامة ولا شيئا إلا أن تودوني لقرابتي منكم، وأن تكونوا أولى بي من غيركم", "qawaid": [], "tabi": ""}]}, {"id": 5809, "kinds": "غيره", "text": "لم يذكر ابن جرير (20/ 503) في قوله: {ومن يقترف حسنة} غير قول السُّدّيّ.", "mawaqif": []}, {"id": 5810, "kinds": "غيره", "text": "لم يذكر ابنُ جرير (20/ 503) في قوله: {نزد له فيها حسنا} غير قول ابن زيد.", "mawaqif": []}], "24": [{"id": 5811, "kinds": "نقد", "text": "انتقد ابنُ عطية (7/ 514) -مستندًا إلى السياق- قولَ مجاهد، فقال: «وقال مجاهد في كتاب الثعلبي وغيره: المعنى: {فَإنْ يَشَإ اللَّهُ يَخْتِمْ عَلى قَلْبِكَ} بالصبر لأذى الكفار، ويربط عليه بالجلد. فهذا تأويل لا يتضمن الرد على مقالتهم». وبمعناه قول مقاتل.", "mawaqif": [{"taliq": 5811, "mi": 0, "aya": 24, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 514", "qawl": "مجاهد", "nass": "وقال مجاهد في كتاب الثعلبي وغيره: المعنى: {فإن يشإ الله يختم على قلبك} بالصبر لأذى الكفار، ويربط عليه بالجلد. فهذا تأويل لا يتضمن الرد على مقالتهم", "qawaid": ["السياق"], "tabi": ""}]}, {"id": 5812, "kinds": "ترجيح،نقد،توجيه،بيان،حصر", "text": "لم يذكر ابنُ جرير (20/ 504) غير قول السُّدّي، وقتادة.\nووجّه ابنُ عطية (7/ 514) معنى الآية على ما جاء فيهما، فقال: «وقوله تعالى: {فَإنْ يَشَإ اللَّهُ يَخْتِمْ} معناه في قول قتادة وفرقة من المفسرين: ينسيك القرآن. والمراد: الرد على مقالة الكفار وبيان إبطالها، وذلك كأنه يقول: وكيف يصح أن تكون مفتريًا وأنت مِن الله بمرأى ومسمع، وهو قادر لو شاء على أن يختم على قلبك فلا تعقل ولا تنطق ولا يستمر افتراؤك؟! فمقصد اللفظ هذا المعنى، وحذف ما يدل عليه الظاهر اختصارًا واقتصارًا».\nورجّح ابنُ القيم (2/ 426 - 428) -مستندًا إلى اللغة، والسياق، ودلالة العقل- قول قتادة، وانتقد قول مجاهد من وجوه كثيرة: 1 - أنّ هذا خرج جوابًا لهم وتكذيبًا لقولهم: إنّ محمدًا كذب على الله وافترى عليه هذا القرآن. فأجابهم بأحسن جواب، وهو أن الله تعالى قادر لا يعجزه شيء، فلو كان كما تقولون لختم على قلبه. 2 - أن مجرد الربط على قلبه بالصبر على أذاهم يصدر من المحقّ والمُبطل، فلا يدل ذلك على التمييز بينهما ولا يكون فيه ردّ لقولهم، فإن الصبر على أذى المكذّب لا يدل بمجرده على صدق المخبر. 3 - أن الرابط على قلب العبد لا يقال له: ختم على قلبه. ولا يُعرف هذا في عُرف المخاطب، ولا لغة العرب، ولا هو المعهود في القرآن. 4 - أنه لا دلالة في سياق الآية على الصبر بوجهٍ ما، لا بالمطابقة ولا التضمن، ولا اللزوم. 5 - أن الختم على القلب لا يستلزم الصبر، بل قد يختم على قلب العبد ويسلبه صبره، بل إذا ختم على القلب زال الصبر وضعف، بخلاف الربط على القلب فإنه يستلزم الصبر.", "mawaqif": [{"taliq": 5812, "mi": 0, "aya": 24, "alam": "ابن عطية", "fil": "وجه", "kind": "توجيه", "ref": "7/ 514", "qawl": "", "nass": "وقوله تعالى: {فإن يشإ الله يختم} معناه في قول قتادة وفرقة من المفسرين: ينسيك القرآن. والمراد: الرد على مقالة الكفار وبيان إبطالها، وذلك كأنه يقول: وكيف يصح أن تكون مفتريا وأنت من الله بمرأى ومسمع، وهو قادر لو شاء على أن يختم على قلبك فلا تعقل ولا تنطق ولا يستمر افتراؤك؟! فمقصد اللفظ هذا المعنى، وحذف ما يدل عليه الظاهر اختصارا واقتصارا", "qawaid": [], "tabi": ""}, {"taliq": 5812, "mi": 0, "aya": 24, "alam": "ابن القيم", "fil": "رجح", "kind": "ترجيح", "ref": "2/ 426 - 428", "qawl": "قتادة", "nass": "", "qawaid": ["اللغة", "السياق", "الدلالة العقلية"], "tabi": ""}]}], "25": [{"id": 5813, "kinds": "خلاف،ترجيح،توجيه،تعليق،نقل", "text": "ذكر ابنُ جرير (20/ 505) قراءتي التاء والياء من {تفعلون}، ووجّههما، فقال: «اختلفت القراء في قراءة ذلك، فقرأته عامة قراء المدينة والبصرة: «يَفْعَلُونَ» بالياء، بمعنى: ويعلم ما يفعل عباده. وقرأته عامة قراء الكوفة: {تفعلون} بالتاء على وجه الخطاب».\nوبنحوه قال ابنُ عطية (7/ 515).\nثم علّق ابنُ جرير عليهما قائلًا: «والصواب من القول في ذلك عندي أنهما قراءتان مشهورتان في قراءة الأمصار، متقاربتا المعنى، فبأيتهما قرأ القارئ فمصيب». ثم رجّح -مستندًا إلى السياق- قراءة الياء بقوله: «غير أن الياء أعجب إلَيَّ؛ لأن الكلام من قبل ذلك جرى على الخبر، وذلك قوله: {وهو الذي يقبل التوبة عن عباده}».", "mawaqif": [{"taliq": 5813, "mi": 0, "aya": 25, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 505", "qawl": "", "nass": "اختلفت القراء في قراءة ذلك، فقرأته عامة قراء المدينة والبصرة: «يفعلون", "qawaid": [], "tabi": ""}, {"taliq": 5813, "mi": 0, "aya": 25, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 515", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5813, "mi": 0, "aya": 25, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "", "qawl": "", "nass": "والصواب من القول في ذلك عندي أنهما قراءتان مشهورتان في قراءة الأمصار، متقاربتا المعنى، فبأيتهما قرأ القارئ فمصيب", "qawaid": ["السياق"], "tabi": ""}]}], "26": [{"id": 5814, "kinds": "خلاف،تعليق،نقل", "text": "لم يذكر ابن جرير (20/ 507) في قوله: {ويزيدهم من فضله} غير قول معاذ.\nعلى هذا القول الذي قاله معاذ وابن عباس فقوله: {يستجيب} بمعنى: يجيب، وهو ما ذكره ابنُ عطية (7/ 515 - 516)، ثم علَّق عليه بقوله: \"والعرب تقول: أجاب واستجاب؛ بمعنىً، ومنه قول الشاعر:\nوداع دعا يا مَن يجيب إلى الندى فلم يستجبه عند ذاك مجيب.\nو {الَّذِينَ} -على هذا القول- مفعول بـ {يَسْتَجِيبُ} «. ثم أورد في معنى قوله: {ويستجيب} قولين آخرين: الأول: ويستدعي الذين آمنوا الإجابة من ربهم بالأعمال الصالحة. وعلَّق عليه قائلًا:» وحملت هذه الفرقة استجاب على المعهود من باب استفعل، أي: طلب الشيء، و {الَّذِينَ} على هذا القول فاعل بـ {يَسْتَجِيبُ} «. الثاني: ويجيب الذين آمنوا ربهم. وعلّق عليه قائلًا:» فـ {الذين} فاعل بمعنى: يجيبون شرعه ورسالته\".", "mawaqif": [{"taliq": 5814, "mi": 0, "aya": 26, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 515 - 516", "qawl": "الشاعر", "nass": ". ثم أورد في معنى قوله: {ويستجيب} قولين آخرين: الأول: ويستدعي الذين آمنوا الإجابة من ربهم بالأعمال الصالحة. وعلق عليه قائلا:", "qawaid": [], "tabi": ""}]}], "28": [{"id": 5816, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 517) القول بأن الرحمة المطر، وعلّق عليه، فقال: «قالت فرقة: أراد بالرحمة: المطر، وعدد النعمة بعينها بلفظين الثاني منهما يؤكد الأول». ثم ذكر قولًا آخر أنها الشمس، وعلّق عليه، فقال: «وقالت فرقة: الرحمة في هذا الموضع: الشمس، فذلك تعديد نعمة غير الأولى، وذلك أن المطر إذا ألمّ بعد القنط حسُن موقعه، فإذا دام سئم، فتجيء الشمس بعده عظيمة الموضع».", "mawaqif": [{"taliq": 5816, "mi": 0, "aya": 28, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 517", "qawl": "بأن الرحمة", "nass": "قالت فرقة: أراد بالرحمة: المطر، وعدد النعمة بعينها بلفظين الثاني منهما يؤكد الأول", "qawaid": [], "tabi": ""}]}], "29": [{"id": 5817, "kinds": "نقد", "text": "على هذا القول الذي قاله مقاتل ومجاهد فالمراد بالدابة: الملائكة والناس. وهو ما انتقده ابنُ عطية (7/ 518) مستندًا لمخالفته اللغة، فقال: «وبعيدٌ غيرُ جارٍ على عُرف اللغة أن تقع الدابة على الملائكة».", "mawaqif": [{"taliq": 5817, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "انتقده", "kind": "نقد", "ref": "7/ 518", "qawl": "", "nass": "وبعيد غير جار على عرف اللغة أن تقع الدابة على الملائكة", "qawaid": ["اللغة"], "tabi": ""}]}], "30": [{"id": 5818, "kinds": "تعليق،نقل", "text": "ذكر ابنُ جرير (20/ 513) هذا الأثر، ثم علّق قائلًا: «حدّث هذا الحديث الهيثم بن الربيع، فقال: فيه أيوب عن أبي قلابة، عن أنس، أن أبا بكر? كان جالسًا عند النبي صلى الله عليه وسلم، فذكر الحديث، وهو غلط، والصواب عن أبي إدريس».", "mawaqif": [{"taliq": 5818, "mi": 0, "aya": 30, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "20/ 513", "qawl": "", "nass": "حدث هذا الحديث الهيثم بن الربيع، فقال: فيه أيوب عن أبي قلابة، عن أنس، أن أبا بكر? كان جالسا عند النبي صلى الله عليه وسلم، فذكر الحديث، وهو غلط، والصواب عن أبي إدريس", "qawaid": [], "tabi": ""}]}], "32": [{"id": 5819, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 515 - 516) غير قول السُّدّيّ، ومجاهد.", "mawaqif": []}], "37": [{"id": 5821, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 521) غير قول السُّدّيّ.", "mawaqif": []}], "38": [{"id": 5822, "kinds": "تعليق،نقل", "text": "ذكر ابن زيد ومقاتل أن هذه الآية في الأنصار، وقد علّق ابنُ عطية (7/ 523) على هذا القول، فقال: «والظاهر أن الله تعالى مدح كلَّ مَن اتصف بهذه الصفة كائنًا مَن كان، وهل حصل الأنصار في هذه الصفة إلا بعد سبق المهاجرين لها -رضي الله تعالى عن جميعهم- بمَنِّه».", "mawaqif": [{"taliq": 5822, "mi": 0, "aya": 38, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 523", "qawl": "", "nass": "والظاهر أن الله تعالى مدح كل من اتصف بهذه الصفة كائنا من كان، وهل حصل الأنصار في هذه الصفة إلا بعد سبق المهاجرين لها -رضي الله تعالى عن جميعهم- بمنه", "qawaid": [], "tabi": ""}]}], "40": [{"id": 5824, "kinds": "ترجيح،توجيه،بيان،تعليق،نقل", "text": "أفاد قولُ ابن زيد تخصيص الآية بالمشركين إن آذوا المسلمين، وقد وجّهه ابنُ جرير (20/ 524) بقوله: «فعلى قول ابن زيد هذا تأويل الكلام: وجزاء سيئة من المشركين إليكم سيئة مثلها منكم إليهم، وإن عفوتم وأصلحتم في العفو فأجركم في عفوكم عنهم إلى الله، إنه لا يحب الظالمين. وهذا على قوله كقول الله عز وجل: {فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم واتقوا الله} [البقرة: 194]، وللذي قال من ذلك وجه». ثم رجّح -مستندًا إلى دلالة العموم، وعدم الدليل على النسخ- أن الصواب: «أن تُحمل الآية على الظاهر، ما لم ينقله إلى الباطن ما يجب التسليم له، وأن لا يحكم لحكم في آية بالنسخ إلا بخبر يقطع العذر أو حجة يجب التسليم لها، ولم تثبت حجة في قوله: {وجزاء سيئة سيئة مثلها} أنه مراد به المشركون دون المسلمين، ولا بأنّ هذه الآية منسوخة فنسلم لها بأن ذلك كذلك».\nوذكر ابنُ عطية (7/ 524) أنّ الزجّاج قال: سمّى العقوبة باسم الذنب. وعلَّق عليه بقوله: «وهذا إذا أخذنا السيئة في حق الله تعالى بمعنى المعصية، وذلك أن المجازاة من الله تعالى ليست سيئة، إلا بأن سُميّت باسم موجبتها، وأما إن أخذنا السيئة بمعنى المعصية في حقّ البشر، أي: يسوء هذا هذا ويسوؤه الآخر، فلسنا نحتاج إلى أن نقول: سمى العقوبة باسم الذنب، بل الفعل الأول والآخر سيئة».", "mawaqif": [{"taliq": 5824, "mi": 0, "aya": 40, "alam": "ابن جرير", "fil": "وجهه", "kind": "توجيه", "ref": "20/ 524", "qawl": "", "nass": "فعلى قول ابن زيد هذا تأويل الكلام: وجزاء سيئة من المشركين إليكم سيئة مثلها منكم إليهم، وإن عفوتم وأصلحتم في العفو فأجركم في عفوكم عنهم إلى الله، إنه لا يحب الظالمين. وهذا على قوله كقول الله عز وجل: {فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم واتقوا الله} [البقرة: 194]، وللذي قال من ذلك وجه", "qawaid": ["العموم", "عدم الدليل على غيره"], "tabi": ""}, {"taliq": 5824, "mi": 0, "aya": 40, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 524", "qawl": "", "nass": "وهذا إذا أخذنا السيئة في حق الله تعالى بمعنى المعصية، وذلك أن المجازاة من الله تعالى ليست سيئة، إلا بأن سميت باسم موجبتها، وأما إن أخذنا السيئة بمعنى المعصية في حق البشر، أي: يسوء هذا هذا ويسوؤه الآخر، فلسنا نحتاج إلى أن نقول: سمى العقوبة باسم الذنب، بل الفعل الأول والآخر سيئة", "qawaid": [], "tabi": ""}]}], "43": [{"id": 5826, "kinds": "بيان", "text": "قال ابنُ عطية (7/ 525): «من رأى أن هذه الآية هي فيما بين المؤمنين والمشركين، وأن الصبر للمشركين كان أفضل؛ قال: إن الآية نُسخت بآية السيف. ومَن رأى أن الآية إنما هي بين المؤمنين قال: هي محكمة، والصبر والغفران أفضل إجماعًا».", "mawaqif": [{"taliq": 5826, "mi": 0, "aya": 43, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 525", "qawl": "", "nass": "من رأى أن هذه الآية هي فيما بين المؤمنين والمشركين، وأن الصبر للمشركين كان أفضل؛ قال: إن الآية نسخت بآية السيف. ومن رأى أن الآية إنما هي بين المؤمنين قال: هي محكمة، والصبر والغفران أفضل إجماعا", "qawaid": [], "tabi": ""}]}], "45": [{"id": 5827, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 526) أن قوله: {مِنَ الذُّلِّ} يحتمل أن يتعلق بـ {خاشِعِينَ}، ويحتمل أن يتعلق بما بعده من قوله: {يَنْظُرُونَ}. ثم قال: «والخشوع: الاستكانة، وقد يكون محمودًا، وما يخرجه إلى حالة الذم قوله: {مِنَ الذُّلِّ} فيقوى -على هذا- تعلق {مِنَ} بـ {خاشِعِينَ}».", "mawaqif": [{"taliq": 5827, "mi": 0, "aya": 45, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 526", "qawl": "", "nass": "والخشوع: الاستكانة، وقد يكون محمودا، وما يخرجه إلى حالة الذم قوله: {من الذل} فيقوى -على هذا- تعلق {من} ب {خاشعين}", "qawaid": [], "tabi": ""}]}], "50": [{"id": 5830, "kinds": "تعليق،نقل", "text": "ساق ابنُ عطية (7/ 529) قول محمد بن الحنفية، ثم علَّق بقوله: «أي: يجعل في بطن زوجًا من الذرية ذكرًا وأنثى».", "mawaqif": [{"taliq": 5830, "mi": 0, "aya": 50, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 529", "qawl": "محمد بن", "nass": "أي: يجعل في بطن زوجا من الذرية ذكرا وأنثى", "qawaid": [], "tabi": ""}]}, {"id": 5831, "kinds": "ترجيح،توجيه،نقل", "text": "رجّح ابنُ جرير (20/ 536 - 539) -مستندًا إلى أقوال السلف- أن قوله: {أو يزوجهم ذكرانا وإناثا} معناه: أن يرزقهم ذكورًا وإناثًا، بأن يجعل حمْل زوجته مرّة ذكرًا ومرّة أنثى. ثم ذكر قول ابن زيد في ذلك.", "mawaqif": [{"taliq": 5831, "mi": 0, "aya": 50, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "20/ 536 - 539", "qawl": "ابن زيد", "nass": "", "qawaid": ["أقوال السلف"], "tabi": ""}]}], "52": [{"id": 5832, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 531) أن قوله: {من أمرنا} يعني: «واحد من أمورنا». ثم ذكر احتمالًا آخر، فقال: «ويحتمل أن يكون الأمر بمعنى الكلام».", "mawaqif": [{"taliq": 5832, "mi": 0, "aya": 52, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 531", "qawl": "", "nass": "واحد من أمورنا", "qawaid": [], "tabi": ""}]}, {"id": 5834, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (20/ 543 - 544) غير قول السُّدّي، وقول قتادة من طريق معمر.", "mawaqif": []}]}, "athar": {"68992": {"num": 68992, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري، في قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، قال: ما كان نبيُّ الله صلى الله عليه وسلم يسألُ على هذا القرآن أجرًا، ولكنَّه أمرهم أن يتقرّبوا إلى الله بطاعته، وحُبِّ كتابه."}, "68993": {"num": 68993, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق الربيع بن أنس- في قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، قال: كلّ مَن تقرّب إلى الله بطاعته وجَبَتْ عليك محبتُه."}, "68994": {"num": 68994, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق عوف- في قوله: {إلّا المَوَدَّةَ فِي القُرْبى}، قال: إلا التقرّب إلى الله بالعمل الصالح."}, "68995": {"num": 68995, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق منصور بن زاذان- أنه قال في هذه الآية: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، قال: القُربى إلى الله."}, "68996": {"num": 68996, "aya": 23, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق قتادة- في قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}: قل لا أسألكم على ما جئتكم به، وعلى هذا الكتاب أجرًا، إلا المودّة في القُربى، إلا أن تودّدوا إلى الله بما يقرّبكم إليه، وعمل بطاعته."}, "68997": {"num": 68997, "aya": 23, "qail": "عبد الله بن القاسم", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن عبد الله بن القاسم -من طريق قُرَّة- في قوله: {إلّا المَوَدَّةَ فِي القُرْبى}، قال: أُمرت أن تَصل قرابتك."}, "68998": {"num": 68998, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، قال: كلّ قريش كانت بينهم وبين رسول الله صلى الله عليه وسلم قرابة، فقال: قل لا أسألكم عليه أجرًا إلا أن تودّوني بالقرابة التي بيني وبينكم."}, "68999": {"num": 68999, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}: وإن الله تبارك وتعالى أمر محمدًا صلى الله عليه وسلم أن لا يسأل الناس على هذا القرآن أجرًا إلا أن يصلوا ما بينه وبينهم من القرابة، وكل بطون قريش قد ولدَتْه، وبينه وبينهم قرابة."}, "69000": {"num": 69000, "aya": 23, "qail": "أبي إسحاق السبيعي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن أبي إسحاق السبيعي، قال: سألتُ عمرو بن شعيب عن قول الله عز وجل: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}. قال: قُربى النبي صلى الله عليه وسلم."}, "69001": {"num": 69001, "aya": 23, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- في قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، قال: لم يكن بطنٌ مِن بطون قريش إلا لرسول الله صلى الله عليه وسلم فيهم ولادة، فقال: قل لا أسألكم عليه أجرًا إلا أن تودّوني؛ لقرابتي منكم."}, "69002": {"num": 69002, "aya": 23, "qail": "عطاء بن دينار", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عطاء بن دينار -من طريق سعيد بن أبي أيوب- في قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، يقول: لا أسألكم على ما جئتكم به أجرًا، إلا أن تودّوني في قرابتي منكم، وتمنعوني من الناس."}, "69122": {"num": 69122, "aya": 39, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- ذكر المهاجرين صِنفين: صِنفًا عفا، وصِنفًا انتصر، وقرأ: {والَّذِينَ يَجْتَنِبُونَ كَبائِرَ الإثْمِ والفَواحِشَ وإذا ما غَضِبُوا هُمْ يَغْفِرُونَ} قال: فبدأ بهم، {والَّذِينَ اسْتَجابُوا لِرَبِّهِمْ} إلى قوله: {ومِمّا رَزَقْناهُمْ يُنْفِقُونَ} وهم الأنصار. ثم ذكر الصِّنف الثالث، فقال: {والَّذِينَ إذا أصابَهُمُ البَغْيُ هُمْ يَنْتَصِرُونَ} من المشركين."}, "69004": {"num": 69004, "aya": 23, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، قال: يقول: إلا أن تودّوني في قرابتي، كما توادّون في قرابتكم وتواصلون بها، ليس هذا الذي جئتُ به يقطع ذلك عنِّي، فلستُ أبتغي على الذي جئتُ به أجرًا آخذه على ذلك منكم."}, "69006": {"num": 69006, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس في قوله: {ومَن يَقْتَرِفْ حَسَنَةً} قال: المودّة لآل محمد."}, "69007": {"num": 69007, "aya": 23, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- في قول الله: {ومَن يَقْتَرِفْ حَسَنَةً}، قال: يعمل حسنة."}, "69009": {"num": 69009, "aya": 23, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ومَن يَقْتَرِفْ حَسَنَةً نَزِدْ لَهُ فِيها حُسْنًا}، قال: مَن يعمل خيرًا نَزدْ له. الاقتراف: العمل."}, "69010": {"num": 69010, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {إنَّ اللَّهَ غَفُورٌ شَكُورٌ}، قال: غفور للذُّنوب، شكور للحسنات يضاعفها."}, "69012": {"num": 69012, "aya": 23, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "قال عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {إنَّ اللَّهَ غَفُورٌ شَكُورٌ}، قال: غفَر لهم الذُّنوب، وشكر لهم نِعَمًا هو أعطاهم إيّاها، وجعلها فيهم."}, "69145": {"num": 69145, "aya": 41, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية، والنسخ فيها", "text": "عن قتادة بن دعامة -من طريق سعيد- {ولَمَنِ انْتَصَرَ بَعْدَ ظُلْمِهِ فَأُولَئِكَ ما عَلَيْهِمْ مِن سَبِيلٍ}، قال: هذا في الخُماشَةِ تكون بين الناس، فأمّا إنْ ظلمك رجل فلا تظلمه، وإن فجَر بك فلا تفْجُر به، وإن خانك فلا تخُنه؛ فإن المؤمن هو الموفّي المؤدّي، وإنّ الفاجر هو الخائن الغادر."}, "69230": {"num": 69230, "aya": 52, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "", "text": "عن الحسن البصري -من طريق قتادة- في قوله: {رُوحًا مِن أمْرِنا}، قال: رحمة مِن أمرنا."}, "69150": {"num": 69150, "aya": 41, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية، والنسخ فيها", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ولَمَنِ انْتَصَرَ بَعْدَ ظُلْمِهِ فَأُولَئِكَ ما عَلَيْهِمْ مِن سَبِيلٍ}، قال: لمن انتصر بعد ظُلمه من المؤمنين انتصر من المشركين، وهذا قد نُسخ، وليس هذا في أهل الإسلام، ولكن في أهل الإسلام الذي قال الله: {ادْفَعْ بِالَّتِي هِيَ أحْسَنُ فَإذا الَّذِي بَيْنَكَ وبَيْنَهُ عَداوَةٌ كَأَنَّهُ ولِيٌّ حَمِيمٌ} [فصلت: 34]."}, "69232": {"num": 69232, "aya": 52, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- في قوله: {وكَذَلِكَ أوْحَيْنا إلَيْكَ رُوحًا مِن أمْرِنا}، قال: وحيًا مِن أمرنا."}, "69164": {"num": 69164, "aya": 45, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {يَنْظُرُونَ مِن طَرْفٍ خَفِيٍّ}، قال: ذليل."}, "69165": {"num": 69165, "aya": 45, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "قال مجاهد بن جبر -من طريق ابن أبي نجيح-، مثله."}, "69167": {"num": 69167, "aya": 45, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد-، مثله."}, "68983": {"num": 68983, "aya": 23, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن سعيد بن جُبير -من طريق أبي العالية- {إلّا المَوَدَّةَ فِي القُرْبى}، قال: قُرْبى رسول الله صلى الله عليه وسلم."}, "69059": {"num": 69059, "aya": 30, "qail": "قتادة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة: {وما أصابَكُمْ مِن مُصِيبَةٍ} الآية، قال: ذُكِر لنا: أنّ نبي الله صلى الله عليه وسلم كان يقول: «لا يصيب ابن آدم خدْش عود، ولا عثْرة قدم، ولا اختلاج عرق إلا بذنب، وما يعفو الله عنه أكثر»."}, "68984": {"num": 68984, "aya": 23, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، قال: أن تتبعوني، وتصدّقوني، وتَصِلوا رحمي."}, "69062": {"num": 69062, "aya": 30, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- قوله: {وما أصابَكُمْ مِن مُصِيبَةٍ فَبِما كَسَبَتْ أيْدِيكُمْ}، قال: تُعجّل للمؤمنين عقوبتهم بذنوبهم في الدنيا، ولا يؤاخذون بها في الآخرة."}, "69239": {"num": 69239, "aya": 52, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {ما كُنْتَ تَدْرِي ما الكِتابُ ولا الإيمانُ}: يعني: محمدًا صلى الله عليه وسلم."}, "69242": {"num": 69242, "aya": 52, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {ولَكِنْ جَعَلْناهُ نُورًا نَهْدِي بِهِ مَن نَشاءُ مِن عِبادِنا}: يعني: بالقرآن."}, "69119": {"num": 69119, "aya": 39, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّي -من طريق أسباط- {والَّذِينَ إذا أصابَهُمُ البَغْيُ هُمْ يَنْتَصِرُونَ}، قال: ينتصرون مِمَّن بغى عليهم مِن غير أن يعتدوا."}, "68961": {"num": 68961, "aya": 23, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، ونسخها", "text": "عن ابن عباس -من طريق مقسم- قال: قالت الأنصار: فعلنا، وفعلنا. وكأنهم فخروا، فقال ابن عباس: لنا الفضلُ عليكم. فبلغ ذلك رسولَ الله صلى الله عليه وسلم، فأتاهم في مجالسهم، فقال: «يا معشر الأنصار، ألم تكونوا أذِلَّة فأعزّكم الله؟». قالوا: بلى، يا رسول الله. قال: «أفلا تجيبوني؟». قالوا: ما نقول، يا رسول الله؟ قال: «ألا تقولون: ألم يُخرجك قومك فآويناك؟! أولم يكذِّبوك فصدّقناك؟! أولم يخذلوك فنصرناك؟!». فما زال يقول حتى جَثوا على الرُّكب، وقالوا: أموالنا وما في أيدينا لله ورسوله. فنزلت: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}."}, "68962": {"num": 68962, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، ونسخها", "text": "عن عبد الله بن عباس -من طريق عثمان أبي اليقظان، عن سعيد بن جبير- قال: قالت الأنصار فيما بينهم: لو جمعْنا لرسول الله صلى الله عليه وسلم مالًا، فبسَط يده، لا يحول بينه وبينه أحد. فقالوا: يا رسول الله، إنّا أردنا أن نجمع لك مِن أموالنا. فأنزل الله: {لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}. فخرجوا مختلفين، فقالوا: لِمَن تُرَون ما قال رسولُ الله صلى الله عليه وسلم؟ فقال بعضهم: إنما قال هذا لِنُقاتل عن أهل بيته وننصرهم. فأنزل الله: {أمْ يَقُولُونَ افْتَرى عَلى اللَّهِ كَذِبًا} إلى قوله: {وهُوَ الَّذِي يَقْبَلُ التَّوْبَةَ عَنْ عِبادِهِ}، فعرض لهم بالتوبة إلى قوله: {ويَسْتَجِيبُ الَّذِينَ آمَنُوا وعَمِلُوا الصّالِحاتِ ويَزِيدُهُمْ مِن فَضْلِهِ} هم الذين قالوا هذا، أن يتوبوا إلى الله، ويستغفرونه."}, "68963": {"num": 68963, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، ونسخها", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- قال: نزلت هذه الآية بمكة، وكان المشركون يُؤذون رسول الله صلى الله عليه وسلم؛ فأنزل الله تعالى: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى} إلا الحفظ لي في قرابتي فيكم. قال: المودّة إنّما هي لرسول الله صلى الله عليه وسلم في قرابته، فلما هاجر إلى المدينة أحبَّ أن يُلحقه بإخوته من الأنبياء، فقال: {قُلْ ما سَأَلْتُكُمْ مِن أجْرٍ فَهُوَ لَكُمْ إنْ أجْرِيَ إلّا عَلى اللَّهِ} [سبأ: 47] يعني: ثوابه وكرامته في الآخرة. كما قال نوح عليه السلام: {وما أسْأَلُكُمْ عَلَيْهِ مِن أجْرٍ إنْ أجْرِيَ إلّا عَلى رَبِّ العالَمِينَ} [الشعراء: 109] وكما قال هود، وصالح، وشعيب، لم يستَثْنوا أجرًا كما استثنى النبيُّ صلي الله عليه وسلم، فردّ عليهم، وهي منسوخة."}, "68966": {"num": 68966, "aya": 23, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، ونسخها", "text": "قال قتادة بن دعامة: اجتمع المشركون في مجمع لهم، فقال بعضُهم لبعض: أترون محمدًا صلى الله عليه وسلم يسأل على ما يتعاطاه أجرًا؟ فأنزل الله تعالى: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}."}, "68969": {"num": 68969, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق خُصيف، عن سعيد بن جبير- قال: قال لهم رسول الله صلى الله عليه وسلم: «لا أسألُكم عليه أجرًا إلا أن تَوَدُّوني في نفسي لقرابتي منكم، وتحفظوا القرابة التي بيني وبينكم»."}, "68970": {"num": 68970, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق حسين الأشقر، عن قيس، عن الأعمش، عن سعيد بن جبير- قال: لَمّا نزلت هذه الآية: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى} قالوا: يا رسول الله، مَن قرابتك هؤلاء الذين وجبت علينا مودّتهم؟ قال: «عليٌّ، وفاطمة، وولداها»."}, "68843": {"num": 68843, "aya": 11, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- قوله: {فاطِرُ السَّماواتِ والأَرْضِ}، قال: خالق."}, "68971": {"num": 68971, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق مجاهد- عن النبي صلى الله عليه وسلم في قوله: {إلّا المَوَدَّةَ فِي القُرْبى}، قال: «لا أسألكم على ما أتيتكم به مِن البينات والهدى أجرًا، إلا أن تَوَدُّوا الله، وأن تقرَّبوا إليه بطاعته»."}, "68972": {"num": 68972, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق مجاهد- قال: قال رسول الله صلى الله عليه وسلم: «{لا أسأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}؛ أن تحفظوني في أهل بيتي، وتودوهم بي»."}, "68846": {"num": 68846, "aya": 11, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- قوله: {جَعَلَ لَكُمْ مِن أنْفُسِكُمْ أزْواجًا ومِنَ الأَنْعامِ أزْواجًا يَذْرَؤُكُمْ فِيهِ}، يقول: يجعل لكم فيه معيشةً تعيشون بها."}, "68847": {"num": 68847, "aya": 11, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {يَذْرَؤُكُمْ فِيهِ}، قال: نسلًا مِن بعد نسل مِن الناس والأنعام."}, "68848": {"num": 68848, "aya": 11, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {يَذْرَؤُكُمْ فِيهِ}، قال: عيشٌ من الله يُعِيشكم فيه. (13/ 133)"}, "68849": {"num": 68849, "aya": 11, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- في قوله: {يَذْرَؤُكُمْ فِيهِ}، قال: يخلقكم."}, "68850": {"num": 68850, "aya": 11, "qail": "منصور بن المعتمر", "tabaqa": "", "bab": "", "text": "عن منصور [بن المعتمر]-من طريق شعبة- قوله: {يَذْرَؤُكُمْ فِيهِ}، قال: يخلقكم."}, "68973": {"num": 68973, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- في قوله: {إلّا المَوَدَّةَ فِي القُرْبى}، قال: كان لرسول الله صلى الله عليه وسلم قرابة مِن جميع قريش، فلمّا كذّبوه، وأبَوْا أن يُبايعوه، قال: «يا قوم، إذا أبيتم أن تُبايعوني فاحفظوا قرابتي فيكم، ولا يكون غيرُكم مِن العرب أولى بحفظي ونُصرتي منكم»."}, "68974": {"num": 68974, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {إلّا المَوَدَّةَ فِي القُرْبى}، قال: إنّ محمدًا قال لقريش: «لا أسألكم مِن أموالكم شيئًا، ولكن أسألكم ألّا تُؤذُونِي لقرابة ما بيني وبينكم؛ فإنّكم قومي، وأحقُّ مَن أطاعني وأجابني»."}, "68976": {"num": 68976, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق طاووس- أنّه سُئِل عن قوله: {إلّا المَوَدَّةَ فِي القُرْبى}. فقال سعيد بن جبير: قُربى آل محمد. فقال ابن عباس: عَجِلْتَ، إنّ النبيّ صلى الله عليه وسلم لم يكن بطن من قريش إلا كان له فيهم قرابة، فقال: إلا أن تصلوا ما بيني وبينكم من القرابة."}, "68977": {"num": 68977, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- قال: … {قُلْ} لهم يا محمد: {لا أسْأَلُكُمْ عَلَيْهِ} يعني: على ما أدعوكم إليه {أجْرًا} عِوَضًا مِن الدنيا {إلّا المَوَدَّةَ فِي القُرْبى} إلا الحفظ لي في قرابتي فيكم. قال: المودّة إنما هي لرسول الله صلى الله عليه وسلم في قرابته …."}, "68979": {"num": 68979, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق أبي مالك- في قوله: {إلّا المَوَدَّةَ فِي القُرْبى}، قال: تحفظوني في قرابتي."}, "68980": {"num": 68980, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في قوله: {إلّا المَوَدَّةَ فِي القُرْبى} قال: إن رسول الله صلى الله عليه وسلم لم يكن في قريش بطنٌ إلا وله فيهم أمٌّ، حتى كانت له من هُذَيل أُمّ، فقال الله: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا} إلا أن تحفظوني في قرابتي؛ إن كذّبتموني فلا تؤذوني."}, "68981": {"num": 68981, "aya": 23, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق يوسف بن مهران- في قوله: {إلّا المَوَدَّةَ فِي القُرْبى}، قال: إلا أن تَوَدُّوني في قرابتي، ولا تُؤْذوني."}, "68982": {"num": 68982, "aya": 23, "qail": "أبي الديلم", "tabaqa": "", "bab": "تفسير الآية", "text": "عن أبي الديلم، قال: لما جِيءَ بعلي بن الحسين أسيرًا، فأُقيم على دَرَج دمشق، قام رجل من أهل الشام، فقال: الحمد لله الذي قتَلكم واستأصَلكم. فقال له علي بن الحسين: أقرأتَ القرآن؟ قال: نعم. قال: أقرأت «آل حم»؟ قال: لا. قال: أما قرأت: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}؟ قال: فإنّكم لأنتم هُم؟ قال: نعم."}, "69248": {"num": 69248, "aya": 52, "qail": "إسماعيل السدي", "tabaqa": "تابعي", "bab": "", "text": "عن إسماعيل السُّدّيّ -من طريق أسباط- {وإنَّكَ لَتَهْدِي إلى صِراطٍ مُسْتَقِيم}، يقول: تدعو إلى دين مستقيم."}, "68990": {"num": 68990, "aya": 23, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن أبي مالك غَزْوان الغِفارِيّ -من طريق هُشَيْم عن حُصين- قال: كان رسول الله صلى الله عليه وسلم واسط النسب من قريش، ليس حيٌّ مِن أحياء قريش إلا وقد ولدوه. قال: فقال الله عز وجل: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى} إلا أن تودّوني؛ لقرابتي منكم، وتحفظوني."}, "68991": {"num": 68991, "aya": 23, "qail": "أبي مالك غزوان الغفاري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن أبي مالك غَزْوان الغِفارِيّ -من طريق عَبْثَر عن حُصين- في هذه الآية: {قُلْ لا أسْأَلُكُمْ عَلَيْهِ أجْرًا إلّا المَوَدَّةَ فِي القُرْبى}، قال: كان رسول الله صلى الله عليه وسلم من بني هاشم، وأمّه من بني زُهْرَة، وأمّ أبيه من بني مخزوم، فقال: احفظوني في قرابتي."}}, "n_athar": {"0": 31, "3": 3, "4": 1, "5": 21, "6": 1, "7": 9, "8": 2, "9": 3, "10": 2, "11": 11, "12": 7, "13": 20, "14": 12, "15": 9, "16": 13, "17": 8, "18": 2, "19": 6, "20": 17, "21": 4, "22": 5, "23": 56, "24": 6, "25": 11, "26": 7, "27": 11, "28": 5, "29": 2, "30": 17, "31": 1, "32": 4, "33": 8, "34": 8, "35": 3, "36": 3, "37": 11, "38": 6, "39": 7, "40": 22, "41": 8, "42": 3, "43": 3, "44": 3, "45": 10, "46": 1, "47": 5, "48": 3, "49": 15, "50": 24, "51": 8, "52": 24, "53": 2}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});